from ortools.sat.python import cp_model
N=8
allowed=[]
for a in range(64):
    ra,ca=divmod(a,N)
    for b in range(64):
        rb,cb=divmod(b,N)
        if (abs(ra-rb),abs(ca-cb)) in [(1,2),(2,1)]:
            allowed.append([a,b])
fixed={0:0,2:27,3:21,10:16,11:1,19:24,21:3,27:51,38:38,50:43,51:60,59:53,61:42}
model=cp_model.CpModel()
x=[model.NewIntVar(0,63,f'x{i}') for i in range(64)]
model.AddAllDifferent(x)
for i,v in fixed.items(): model.Add(x[i]==v)
for i in range(63): model.AddAllowedAssignments([x[i],x[i+1]], allowed)
pos=[model.NewIntVar(0,63,f'p{c}') for c in range(64)]
model.AddInverse(x,pos)
for t in range(64):
    model.AddAllowedAssignments([x[t]], [[c] for c in range(64) if ((c//8+c%8)&1)==(t&1)])
solver=cp_model.CpSolver(); solver.parameters.max_time_in_seconds=60; solver.parameters.num_search_workers=8
res=solver.Solve(model)
print(solver.StatusName(res), solver.WallTime())
if res in (cp_model.OPTIMAL, cp_model.FEASIBLE):
 print([solver.Value(v) for v in x])
else:
 print('conflicts', solver.NumConflicts(), 'branches', solver.NumBranches())
